39	/** True for counts of tokens only; the `tokensPer…` units are ratios and keep their decimals. */
40	function abbreviatesTokens(unit: StatsUnit, shortTokenCounts: boolean) {
41	    return shortTokenCounts && unit === 'tokens';
42	}
43	
44	function formattedValue(row: StatsChartRow, shortTokenCounts: boolean) {
45	    if (!row.available) return 'Unavailable';
46	    if (abbreviatesTokens(row.unit, shortTokenCounts)) return formatTokenCount(row.value);
47	    if (row.unit === 'milliseconds') return formatDurationHms(row.value);
48	    if (row.unit === 'percent') {
49	        return `${new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(row.value)}%`;
50	    }
51	    if (row.unit === 'dollars') {
52	        return new Intl.NumberFormat(undefined, { currency: 'USD', style: 'currency' }).format(row.value);
53	    }
54	
55	    return new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(row.value);
56	}
57	
58	/** Stacked bars label their full height; duration stacks read HH:MM:SS like their individual rows. */
59	function stackTotalLabel(bar: BarRows, total: number, shortTokenCounts: boolean) {
60	    if (abbreviatesTokens(bar.rows[0].unit, shortTokenCounts)) return formatTokenCount(total);
61	    if (bar.rows[0].unit === 'milliseconds') return formatDurationHms(total);
62	
63	    return new Intl.NumberFormat().format(total);
64	}
65	
66	function bucketRows(rows: StatsChartRow[]) {
67	    const buckets = new Map<string, BucketRows>();
68	    for (const row of rows) {
69	        const identity = row.utcBucketStart ?? row.identity;
70	        const current = buckets.get(identity) ?? { identity, label: row.displayLabel, rows: [] };
71	        current.rows.push(row);
72	        buckets.set(identity, current);
73	    }
74	
75	    return [...buckets.values()];
76	}
77	
78	function groupedStackedBars(rows: StatsChartRow[]) {
79	    const groups = new Map<string, BarRows>();
80	    for (const row of rows) {
81	        const identity = row.stackIdentity ?? row.identity;
82	        const current = groups.get(identity) ?? { identity, label: row.stackLabel, rows: [] };
83	        current.rows.push(row);
84	        groups.set(identity, current);
85	    }
86	
87	    return [...groups.values()];
88	}
89	
90	function barsForBucket(bucket: BucketRows, mode: StatsBarMode): BarRows[] {
91	    if (mode === 'stacked') return [{ identity: bucket.identity, label: null, rows: bucket.rows }];
92	    if (mode === 'groupedStacked') return groupedStackedBars(bucket.rows);
93	
94	    return bucket.rows.map((row, index) => ({ identity: `${row.identity}:${index}`, label: null, rows: [row] }));
95	}
96	
97	function barTotal(bar: BarRows) {
98	    return bar.rows.reduce((total, row) => total + Math.max(row.value, 0), 0);
99	}
